custom.tangent:
({ g, v, el, S, geo, w, h }) => {
  // 曲線 f と、その導関数 df。点は x = a にあり、tl で接線が、tr で導関数の記録が現れる
  const f = x => x * x * x / 4 - x, df = x => 3 * x * x / 4 - 1;
  const num = x => { const s = x.toFixed(2); return s === "-0.00" ? "0.00" : s; };
  const Ax = geo.axes(g, { box: { x: 30, y: 10, w: w * 0.58, h: h - 30 }, x: [-3, 3], y: [-2.5, 2.5], grid: true, labels: { x: "$x$", y: "$y$" } });
  geo.plot(g, Ax, f, { color: "accent" });
  const a = v.a, m = df(a);
  if (v.tr > 0 && a > -2.4) geo.plot(el("g", { opacity: v.tr }, g), Ax, df, { from: -2.4, to: a, color: "good" });
  geo.tangent(el("g", { opacity: v.tl }, g), Ax, f, a, { df: m, color: "warn" });
  const [px, py] = Ax.toPx([a, f(a)]), py0 = Ax.toPx([a, 0])[1];
  el("path", { d: `M${px},${py0}V${py}`, stroke: S.muted, "stroke-width": 2, "stroke-dasharray": "6 6" }, g);
  geo.point(g, Ax, [a, f(a)], { color: "warn" });
  const X = w * 0.64;
  geo.tex(g, String.raw`f(x)=\tfrac{1}{4}x^3-x`, { x: X, y: 20, size: 34, color: "accent" });
  geo.tex(el("g", { opacity: v.tr }, g), String.raw`f'(x)=\tfrac{3}{4}x^2-1`, { x: X, y: 90, size: 34, color: "good" });
  geo.tex(el("g", { opacity: v.tl }, g), `f'(${num(a)})=${num(m)}`, { x: X, y: 190, size: 44, color: "warn" });
}

custom.expand:
({ g, v, el, S, geo, w, h }) => {
  // 一辺 x+1 の正方形（x = 2 の比で描く）。cut で切れ目が入って 4 つに分かれ、e で式が展開される
  const c = v.cut, e = v.e, side = h - 80, u = side / 3, xs = 2 * u, x0 = 50, y0 = 60;
  const parts = [[x0, y0, xs, xs, "accent", "$x^2$"], [x0 + xs, y0, u, xs, "warn", "$x$"],
    [x0, y0 + xs, xs, u, "warn", "$x$"], [x0 + xs, y0 + xs, u, u, "good", "$1$"]];
  for (const [x, y, pw, ph, col] of parts)
    el("rect", { x, y, width: pw, height: ph, fill: geo.col(col), "fill-opacity": 0.35 * c }, g);
  geo.polygon(g, [[x0, y0], [x0 + side, y0], [x0 + side, y0 + side], [x0, y0 + side]], { color: "ink" });
  if (c > 0) {
    el("path", { d: `M${x0 + xs},${y0}V${y0 + side * c}M${x0},${y0 + xs}H${x0 + side * c}`, stroke: S.ink, "stroke-width": 3 }, g);
    const lg = el("g", { opacity: c }, g);
    for (const [x, y, pw, ph, col, lab] of parts) geo.label(lg, [x + pw / 2, y + ph / 2], lab, { color: col, size: 34 });
  }
  // 上の辺の長さ: 切る前は x+1、切った後は x と 1
  geo.label(el("g", { opacity: 1 - c }, g), [x0 + side / 2, y0 - 26], "$x+1$", { size: 28 });
  const sg = el("g", { opacity: c }, g);
  geo.label(sg, [x0 + xs / 2, y0 - 26], "$x$", { size: 28 });
  geo.label(sg, [x0 + xs + u / 2, y0 - 26], "$1$", { size: 28 });
  const X = x0 + side + 120;
  geo.tex(el("g", { opacity: e }, g), String.raw`(x+1)^2=`, { x: X, y: h / 2 - 110, size: 44, color: "muted" });
  geo.texMorph(g, String.raw`(\cssId{x}{x}\cssId{p}{+}\cssId{one}{1})^{\cssId{two}{2}}`,
    String.raw`\cssId{x}{x}^{\cssId{two}{2}}\cssId{p}{+}2x+\cssId{one}{1}`, e, { x: X, y: h / 2 - 30, size: 64 });
}

custom.sales:
({ g, v, el, S, geo, w, h }) => {
  // 月の売上 100 万円が、毎月 r ずつ伸びる。伸び率を上げたら、2% のときの高さを横線で残して比べる
  const r = v.g, sales = (rate, m) => 100 * Math.pow(1 + rate, m - 1);
  const Ax = geo.axes(g, { box: { x: 70, y: 20, w: w * 0.58, h: h - 50 }, x: [0.3, 12.7], y: [0, 200], ticks: { x: 1, y: 50 }, labels: { y: "万円" } });
  for (let m = 1; m <= 12; m++) {
    geo.bar(g, Ax, m, sales(r, m), { color: m === 12 ? "warn" : "accent", opacity: 0.85 });
    if (r > 0.0201) {
      const [x0, y] = Ax.toPx([m - 0.3, sales(0.02, m)]), x1 = Ax.toPx([m + 0.3, 0])[0];
      el("path", { d: `M${x0},${y}H${x1}`, stroke: S.ink, "stroke-width": 3, "stroke-dasharray": "5 4" }, g);
    }
  }
  const X = w * 0.66, last = sales(r, 12);
  geo.label(g, [X, 30], "月の伸び率", { anchor: "start", color: "muted", size: 24 });
  geo.number(g, [X, 80], r * 100, { decimals: 1, unit: "%", anchor: "start", color: "accent", size: 48 });
  geo.label(g, [X, 160], "12 月の売上（万円）", { anchor: "start", color: "muted", size: 24 });
  geo.tex(g, String.raw`100\times${(1 + r).toFixed(3)}^{11}\approx${Math.round(last)}`, { x: X, y: 190, size: 36, color: "warn" });
}
